setup=()=>{
  createCanvas(640,640)
  pg=createGraphics(width/4,height/4)
}

draw=()=> {
  t=frameCount
  pg.background('white')
  .loadPixels()
  for(y=pg.height;y--;){
    for(x=pg.width;x--;){  
      n=noise((x-y)/60,t/120)*256
      x+y&n-t||pg.set(x,y,color('black')) 
    }
  }
  pg.updatePixels()

  translate(width/2,height/2)
  scale(2)
  for(v of [[1,1],[-1,1],[1,-1],[-1,-1]]){
    push()
    scale(v)
    image(pg,0,0)
    pop()
  }
}
